-- 0008: extra properties as bookable units (requests Donald confirms), real property details, and iCal
-- import/export so dates booked on Airbnb / Booking.com / freetobook block Roomboard and the other way round.
-- Not deployed yet: needs Donald's approval. Data section generated by scripts/gen-sql-data.mjs.

-- ---------- columns ----------
alter table properties add column if not exists details jsonb not null default '{}';
alter table rooms add column if not exists details jsonb not null default '{}';
-- request = 'pending': Sheena asked for an extra property and Donald has not answered. null = a booking.
alter table stays add column if not exists request text check (request in ('pending'));
alter table stays add column if not exists requested_by uuid default auth.uid();

